/**
 * File: p2p-kids-marketplace/src/components/__tests__/listing/PriceSuggestionCard.test.tsx
 * MODULE-04 LISTING-V3-008: Unit tests for PriceSuggestionCard
 * 
 * Test Coverage:
 * - Rendering with 4 price tiers
 * - Rendering manual-only mode (no suggestions)
 * - Tier selection
 * - Manual price input
 * - FAQ button
 * - Accessibility
 */

import React from 'react';
import { render, fireEvent } from '@testing-library/react-native';
import { PriceSuggestionCard } from '../../listing/PriceSuggestionCard';
import { PriceTier, PriceSuggestion } from '../../../types/listing';

const mockTiers: PriceSuggestion[] = [
  {
    tier: 'great_deal',
    label: 'Great Deal',
    price: 9.99,
    description: 'Quick sale price',
  },
  {
    tier: 'fair_price',
    label: 'Fair Price',
    price: 13.99,
    description: 'Balanced pricing',
  },
  {
    tier: 'asking_price',
    label: 'Asking Price',
    price: 17.99,
    description: 'Standard market rate',
  },
  {
    tier: 'almost_new',
    label: 'Almost New',
    price: 21.99,
    description: 'Premium pricing',
  },
];

describe('PriceSuggestionCard', () => {
  const mockOnSelectTier = jest.fn();
  const mockOnChangeManual = jest.fn();
  const mockOnShowFaq = jest.fn();

  beforeEach(() => {
    jest.clearAllMocks();
  });

  describe('Rendering with Suggestions', () => {
    it('renders with price tier suggestions', () => {
      const { getByTestId } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      expect(getByTestId('price-suggestion-card')).toBeTruthy();
    });

    it('displays all 4 tier cards', () => {
      const { getByTestId } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      expect(getByTestId('tier-great_deal')).toBeTruthy();
      expect(getByTestId('tier-fair_price')).toBeTruthy();
      expect(getByTestId('tier-asking_price')).toBeTruthy();
      expect(getByTestId('tier-almost_new')).toBeTruthy();
    });

    it('displays tier labels and prices', () => {
      const { getByText } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      expect(getByText('Great Deal')).toBeTruthy();
      expect(getByText('$9.99')).toBeTruthy();
      expect(getByText('Fair Price')).toBeTruthy();
      expect(getByText('$13.99')).toBeTruthy();
    });

    it('displays tier descriptions', () => {
      const { getByText } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      expect(getByText('Quick sale price')).toBeTruthy();
      expect(getByText('Balanced pricing')).toBeTruthy();
    });

    it('displays subtitle when suggestions are available', () => {
      const { getByText } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      expect(getByText('Suggested pricing based on similar items:')).toBeTruthy();
    });

    it('displays OR divider when suggestions exist', () => {
      const { getByText } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      expect(getByText('OR')).toBeTruthy();
    });
  });

  describe('Manual-Only Mode (No Suggestions)', () => {
    it('renders manual input when tiers array is empty', () => {
      const { getByTestId } = render(
        <PriceSuggestionCard
          tiers={[]}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      expect(getByTestId('manual-price-input')).toBeTruthy();
    });

    it('displays "no suggestions" message when no tiers', () => {
      const { getByText } = render(
        <PriceSuggestionCard
          tiers={[]}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      expect(getByText('Not enough data to suggest pricing. Set your price below.')).toBeTruthy();
    });

    it('does not display tier cards when empty', () => {
      const { queryByTestId } = render(
        <PriceSuggestionCard
          tiers={[]}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      expect(queryByTestId('tier-great_deal')).toBeNull();
      expect(queryByTestId('tier-fair_price')).toBeNull();
    });

    it('does not display OR divider when no tiers', () => {
      const { queryByText } = render(
        <PriceSuggestionCard
          tiers={[]}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      expect(queryByText('OR')).toBeNull();
    });
  });

  describe('Tier Selection', () => {
    it('calls onSelectTier when tier card is pressed', () => {
      const { getByTestId } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      fireEvent.press(getByTestId('tier-great_deal'));
      expect(mockOnSelectTier).toHaveBeenCalledWith('great_deal');

      fireEvent.press(getByTestId('tier-fair_price'));
      expect(mockOnSelectTier).toHaveBeenCalledWith('fair_price');
    });

    it('shows selected tier visually', () => {
      const { getByTestId } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier="fair_price"
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      const selectedTier = getByTestId('tier-fair_price');
      expect(selectedTier.props.accessibilityState).toEqual({ selected: true });
    });
  });

  describe('Manual Price Input', () => {
    it('renders manual input field', () => {
      const { getByTestId } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      expect(getByTestId('manual-price-input')).toBeTruthy();
    });

    it('displays currency symbol', () => {
      const { getByText } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      expect(getByText('$')).toBeTruthy();
    });

    it('displays manual value when provided', () => {
      const { getByDisplayValue } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue="25.99"
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      expect(getByDisplayValue('25.99')).toBeTruthy();
    });

    it('calls onChangeManual when text changes', () => {
      const { getByTestId } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      fireEvent.changeText(getByTestId('manual-price-input'), '15.50');
      expect(mockOnChangeManual).toHaveBeenCalledWith('15.50');
    });

    it('has decimal keyboard type', () => {
      const { getByTestId } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      const input = getByTestId('manual-price-input');
      expect(input.props.keyboardType).toBe('decimal-pad');
    });
  });

  describe('FAQ Button', () => {
    it('renders FAQ button when onShowFaq is provided', () => {
      const { getByTestId } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
          onShowFaq={mockOnShowFaq}
        />
      );

      expect(getByTestId('pricing-faq')).toBeTruthy();
    });

    it('does not render FAQ button when onShowFaq is not provided', () => {
      const { queryByTestId } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      expect(queryByTestId('pricing-faq')).toBeNull();
    });

    it('calls onShowFaq when FAQ button is pressed', () => {
      const { getByTestId } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
          onShowFaq={mockOnShowFaq}
        />
      );

      fireEvent.press(getByTestId('pricing-faq'));
      expect(mockOnShowFaq).toHaveBeenCalledTimes(1);
    });
  });

  describe('Accessibility', () => {
    it('has accessible labels for tier buttons', () => {
      const { getByLabelText } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      expect(getByLabelText('Great Deal: $9.99')).toBeTruthy();
      expect(getByLabelText('Fair Price: $13.99')).toBeTruthy();
    });

    it('has accessible hints for tier descriptions', () => {
      const { getByA11yHint } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      expect(getByA11yHint('Quick sale price')).toBeTruthy();
    });

    it('has accessible label for manual input', () => {
      const { getByLabelText } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
        />
      );

      expect(getByLabelText('Manual price input')).toBeTruthy();
    });

    it('has accessible label for FAQ button', () => {
      const { getByLabelText } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
          onShowFaq={mockOnShowFaq}
        />
      );

      expect(getByLabelText('Show pricing FAQ')).toBeTruthy();
    });
  });

  describe('Custom testID', () => {
    it('uses custom testID when provided', () => {
      const { getByTestId } = render(
        <PriceSuggestionCard
          tiers={mockTiers}
          selectedTier={null}
          manualValue=""
          onSelectTier={mockOnSelectTier}
          onChangeManual={mockOnChangeManual}
          testID="custom-price-card"
        />
      );

      expect(getByTestId('custom-price-card')).toBeTruthy();
    });
  });
});

/**
 * File: p2p-kids-marketplace/src/components/__tests__/listing/AIAnalysisCard.test.tsx
 * MODULE-04 LISTING-V3-008: Unit tests for AIAnalysisCard
 * 
 * Test Coverage:
 * - Rendering with AI results
 * - Apply All button (skips filled fields)
 * - Per-field Use buttons
 * - Confidence indicators (high/medium/low)
 * - Dismiss functionality
 * - Entrance animation
 */

import React from 'react';
import { render, fireEvent } from '@testing-library/react-native';
import { AIAnalysisCard } from '../../listing/AIAnalysisCard';
import { AIAnalysisResult } from '../../../types/listing';

const mockAnalysis: AIAnalysisResult = {
  title: {
    value: 'Nike Air Max Sneakers Size 5',
    confidence: 0.85,
  },
  category: {
    value: { id: 'cat-123', label: 'Shoes', icon: '👟' },
    confidence: 0.92,
  },
  condition: {
    value: 'good',
    confidence: 0.75,
  },
  brand: {
    value: 'Nike',
    confidence: 0.88,
  },
  color: {
    value: ['Blue', 'White'],
    confidence: 0.70,
  },
  age_group: {
    value: '6-8',
    confidence: 0.65,
  },
  gender: {
    value: 'boy',
    confidence: 0.55,
  },
};

describe('AIAnalysisCard', () => {
  const mockIsFieldFilled = jest.fn();
  const mockOnApplyAll = jest.fn();
  const mockOnApplyField = jest.fn();
  const mockOnDismiss = jest.fn();

  beforeEach(() => {
    jest.clearAllMocks();
    mockIsFieldFilled.mockReturnValue(false);
  });

  describe('Rendering', () => {
    it('renders with AI analysis', () => {
      const { getByText, getByTestId } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      expect(getByTestId('ai-analysis-card')).toBeTruthy();
      expect(getByText('🤖 AI Suggestions')).toBeTruthy();
    });

    it('displays all AI suggested fields', () => {
      const { getByText } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      expect(getByText('Nike Air Max Sneakers Size 5')).toBeTruthy();
      expect(getByText('Shoes')).toBeTruthy();
      expect(getByText('good')).toBeTruthy();
      expect(getByText('Nike')).toBeTruthy();
      expect(getByText('Blue, White')).toBeTruthy();
      expect(getByText('6-8')).toBeTruthy();
      expect(getByText('boy')).toBeTruthy();
    });
  });

  describe('Confidence Indicators', () => {
    it('displays "High" for confidence >= 0.7', () => {
      const { getAllByText } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      const highConfidence = getAllByText(/High/);
      expect(highConfidence.length).toBeGreaterThan(0);
    });

    it('displays "Medium" for confidence 0.4-0.69', () => {
      const { getAllByText } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      // age_group has confidence 0.65 and gender has 0.55
      const mediumConfidence = getAllByText(/Medium/);
      expect(mediumConfidence.length).toBeGreaterThan(0);
    });

    it('displays "Low" for confidence < 0.4', () => {
      const lowConfidenceAnalysis: AIAnalysisResult = {
        title: {
          value: 'Uncertain Item',
          confidence: 0.35,
        },
      };

      const { getByText } = render(
        <AIAnalysisCard
          analysis={lowConfidenceAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      expect(getByText(/Low/)).toBeTruthy();
    });

    it('displays confidence percentage', () => {
      const { getByText } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      expect(getByText(/85%/)).toBeTruthy(); // title
      expect(getByText(/92%/)).toBeTruthy(); // category
    });
  });

  describe('Apply All Button', () => {
    it('renders Apply All button', () => {
      const { getByTestId } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      expect(getByTestId('apply-all-button')).toBeTruthy();
    });

    it('calls onApplyAll when button is pressed', () => {
      const { getByTestId } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      fireEvent.press(getByTestId('apply-all-button'));
      expect(mockOnApplyAll).toHaveBeenCalledTimes(1);
    });
  });

  describe('Per-Field Use Buttons', () => {
    it('renders Use button for each field', () => {
      const { getByTestId } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      expect(getByTestId('use-title')).toBeTruthy();
      expect(getByTestId('use-category')).toBeTruthy();
      expect(getByTestId('use-condition')).toBeTruthy();
      expect(getByTestId('use-brand')).toBeTruthy();
      expect(getByTestId('use-color')).toBeTruthy();
      expect(getByTestId('use-age_group')).toBeTruthy();
      expect(getByTestId('use-gender')).toBeTruthy();
    });

    it('calls onApplyField with correct field and value', () => {
      const { getByTestId } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      fireEvent.press(getByTestId('use-title'));
      expect(mockOnApplyField).toHaveBeenCalledWith('title', 'Nike Air Max Sneakers Size 5');

      fireEvent.press(getByTestId('use-brand'));
      expect(mockOnApplyField).toHaveBeenCalledWith('brand', 'Nike');
    });

    it('shows "Filled" for already filled fields', () => {
      mockIsFieldFilled.mockImplementation((field) => field === 'title');

      const { getByText, getAllByText } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      // Should have at least one "Filled" button (for title)
      const filledButtons = getAllByText('Filled');
      expect(filledButtons.length).toBeGreaterThanOrEqual(1);
    });

    it('shows "Use" for empty fields', () => {
      const { getAllByText } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      const useButtons = getAllByText('Use');
      expect(useButtons.length).toBeGreaterThan(0);
    });
  });

  describe('Dismiss Button', () => {
    it('renders dismiss button', () => {
      const { getByTestId } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      expect(getByTestId('dismiss-ai-card')).toBeTruthy();
    });

    it('calls onDismiss when button is pressed', () => {
      const { getByTestId } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      fireEvent.press(getByTestId('dismiss-ai-card'));
      expect(mockOnDismiss).toHaveBeenCalledTimes(1);
    });
  });

  describe('Accessibility', () => {
    it('has accessible labels for Use buttons', () => {
      const { getByLabelText } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
          onDismiss={mockOnDismiss}
        />
      );

      expect(getByLabelText('Use AI suggestion for Title')).toBeTruthy();
      expect(getByLabelText('Use AI suggestion for Brand')).toBeTruthy();
    });

    it('has accessible hints for filled fields', () => {
      mockIsFieldFilled.mockImplementation((field) => field === 'title');

      const { getByA11yHint } = render(
        <AIAnalysisCard
          analysis={mockAnalysis}
          isFieldFilled={mockIsFieldFilled}
          onApplyAll={mockOnApplyAll}
          onApplyField={mockOnApplyField}
