        />
      );

      fireEvent.press(getByTestId('gender-unisex'));
      expect(mockOnChange).toHaveBeenCalledWith('unisex');
    });

    it('CRITICAL: "Any" calls onChange with null (not string)', () => {
      const { getByTestId } = render(
        <GenderSelector
